#include <string>

class Solution {
public:
    std::string trafficSignal(long long t, int g, int y, int r) {
        long long cycle = g + y + r;
        long long rem = t % cycle;
        if (rem < g) return "Green";
        if (rem < g + y) return "Yellow";
        return "Red";
    }
};

class Solution {
    public String trafficSignal(long t, int g, int y, int r) {
        long cycle = (long) g + y + r;
        long rem = t % cycle;
        if (rem < g) return "Green";
        if (rem < g + y) return "Yellow";
        return "Red";
    }
}

